{-# LANGUAGE OverloadedStrings #-}

-- | Render the metric catalog as Markdown.
--
-- @docs/metrics.md@ is generated by @admin write-metrics-doc@ and committed, and CI fails if the
-- committed file differs from what the catalog renders. That is the whole mechanism: the prose a
-- reader sees and the SQL the API runs come out of the same file, so a formula cannot be changed
-- without the documentation changing in the same commit.
--
-- The SQL is INLINED rather than linked. A link can point at a file that has since changed; the
-- fenced block in the committed doc is the statement as it was when the number was defined, and
-- the drift gate keeps it current.
module Palmares.Metrics.Doc
  ( renderMetricsDoc,
  )
where

import Data.Text (Text)
import Data.Text qualified as T
import Data.Text.Encoding (decodeUtf8)
import Palmares.Metrics.Catalog

-- | The whole document, deterministically: catalog order, no timestamps, no host names. A
-- generator that embedded the current time would make the drift gate fail on every run.
renderMetricsDoc :: [MetricFormula] -> Text
renderMetricsDoc fs =
  T.unlines $
    [ "<!-- GENERATED FILE — do not edit.",
      "",
      "     Produced by `admin write-metrics-doc` from resources/metric-formulas.json and",
      "     resources/metrics/*.sql. CI runs the generator and fails on any diff, so editing this",
      "     file by hand is reverted by the next build; edit the catalog instead.",
      "-->",
      "",
      "# Published metrics",
      "",
      "Every number this API serves is defined here, and the SQL below is the SQL that produces it:",
      "`Query.Metrics` looks each statement up by `formula_id` and runs it, so there is no second",
      "copy of the arithmetic that could disagree with this page.",
      "",
      "A `null` is not a zero. Where a formula has a `null when` condition, that condition means",
      "\"no data\", and a UI must render it as such rather than as 0%.",
      ""
    ]
      <> concatMap section fs

section :: MetricFormula -> [Text]
section f =
  [ "## " <> mfName f,
    "",
    "| | |",
    "|---|---|",
    "| formula id | `" <> mfFormulaId f <> "` |",
    "| response field | `" <> mfField f <> "` |",
    "| version | " <> T.pack (show (mfVersion f)) <> " |",
    "| source | " <> source <> " |",
    "",
    "**Expression.** " <> mfExpression f,
    ""
  ]
    <> maybe [] (\d -> ["**Denominator.** " <> d, ""]) (mfDenominator f)
    <> maybe [] (\n -> ["**Null when.** " <> n, ""]) (mfNullWhen f)
    <> ["**Inputs.** " <> T.intercalate ", " (map tick (mfInputs f)), ""]
    <> (if null (mfEdgeCases f) then [] else "**Edge cases.**" : "" : map bullet (mfEdgeCases f) <> [""])
    <> sqlBlock
    <> ["Spec: " <> mfSpec f, ""]
  where
    source = case (mfSqlFile f, mfSqlObject f) of
      (Just file, _) -> "`resources/metrics/" <> T.pack file <> "`"
      (_, Just obj) -> "the view `" <> obj <> "`"
      _ -> "none"
    params
      | null (mfParams f) = []
      | otherwise = ["Parameters, in placeholder order: " <> T.intercalate ", " (map tick (mfParams f)), ""]
    sqlBlock = case mfSqlFile f >>= \n -> lookupMetricSql (T.pack n) of
      Nothing -> []
      Just sql -> params <> ["```sql", T.stripEnd (decodeUtf8 sql), "```", ""]
    tick t = "`" <> t <> "`"
    bullet t = "- " <> t
